    var access = token($persistentStore.read("xc_token"));
    if (!access) return null;
    // Legacy access and refresh were not bound to one login. Never trust the old pair.
    var oldHost = $persistentStore.read("xc_host");
    var origin = oldHost ? host(oldHost) : "https://xingchiapi.com";
